import React from "react";
import PropTypes from "prop-types";
import { Input, TextArea } from "@traveloka/soya-components";

class TextInput extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      value: props.value || "",
      errorMessages: [],
    };
  }

  componentDidUpdate(prevProps) {
    if (prevProps.value !== this.props.value) {
      this.setState({
        value: this.props.value || "",
      });
    }
  }

  shouldComponentUpdate(nextProps, nextState) {
    let result = false;
    if (
      nextProps.value !== this.props.value ||
      nextState.value !== this.state.value
    ) {
      result = true;
    }
    return result;
  }

  render() {
    const { errorMessages, value } = this.state;
    const { placeholder, isDisabled, isTextArea } = this.props;

    if (isTextArea) {
      return (
        <TextArea
          {...this.props}
          onChange={this.handleOnChange}
          placeholder={placeholder}
          errorMessages={errorMessages}
          theme="default"
          marginBottom="sm"
        />
      );
    }
    return (
      <Input
        {...this.props}
        value={value}
        isDisabled={isDisabled}
        onChange={this.handleOnChange}
        placeholder={placeholder}
        errorMessages={errorMessages}
        theme="default"
        marginBottom="sm"
      />
    );
  }

  handleOnChange = (value) => {
    const { onChange, name } = this.props;
    const isValid = this.validateInputValue(value);
    this.setState({ value });

    if (onChange) {
      onChange(name, value, isValid);
    }
  };

  validate = (value) => {
    const errorMessages = [];
    const { validators, validationFormat } = this.props;
    for (let i = 0; i < validators.length; i++) {
      const validator = validators[i];
      let validateResult;
      if (validationFormat && i === validators.length - 1) {
        validateResult = validator(value, validationFormat);
      } else {
        validateResult = validator(value);
      }

      const isValid = validateResult && typeof validateResult === "string";
      if (isValid) {
        errorMessages.push(validateResult);
      }
    }

    return {
      errorMessages,
      isValid: !errorMessages.filter((error) => typeof error === "string")[0],
    };
  };

  validateInputValue = (value) => {
    const { isValid, errorMessages } = this.validate(value);
    this.setState({ errorMessages });
    return isValid;
  };
}

TextInput.propTypes = {
  onChange: PropTypes.func,
  placeholder: PropTypes.string,
  validators: PropTypes.array,
  validationFormat: PropTypes.string,
  name: PropTypes.string,
  value: PropTypes.string,
  isDisabled: PropTypes.bool.isRequired,
  isTextArea: PropTypes.bool.isRequired,
};

TextInput.defaultProps = {
  isDisabled: false,
  isTextArea: false,
};

export default TextInput;
